/// What the routes of component `kernel` (Kernel) need from the deployment beyond the implementation of its contracts: the hooks of every one of them.
pub trait KernelHooks:
    DecideIntentHooks
    + PlanIntentNeedsHooks
    + AnswerReadHooks
    + PlanReadNeedsHooks
    + CheckRecordVisibilityHooks
    + ApplyStateDeltaHooks
    + PlanSchemaMigrationHooks
    + HashBytesHooks
    + DeclareEventKindHooks
    + EmitEventHooks
    + DecideTenantOperationHooks
    + ListMySegmentsHooks
    + CountSegmentMembersHooks
    + PreviewSegmentPredicateHooks
    + DefineTriggerHooks
    + RemoveTriggerHooks
    + DefineAutomationHooks
    + RemoveAutomationHooks
    + RecheckAutomationAuthorityHooks
{
}

impl<
        T: DecideIntentHooks
            + PlanIntentNeedsHooks
            + AnswerReadHooks
            + PlanReadNeedsHooks
            + CheckRecordVisibilityHooks
            + ApplyStateDeltaHooks
            + PlanSchemaMigrationHooks
            + HashBytesHooks
            + DeclareEventKindHooks
            + EmitEventHooks
            + DecideTenantOperationHooks
            + ListMySegmentsHooks
            + CountSegmentMembersHooks
            + PreviewSegmentPredicateHooks
            + DefineTriggerHooks
            + RemoveTriggerHooks
            + DefineAutomationHooks
            + RemoveAutomationHooks
            + RecheckAutomationAuthorityHooks,
    > KernelHooks for T
{
}

/// Adds the route of every contract component `kernel` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn kernel_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::Kernel + Send + Sync + 'static,
    H: KernelHooks,
{
    let routes = serve_decide_intent(routes, service.clone(), hooks.clone());
    let routes = serve_plan_intent_needs(routes, service.clone(), hooks.clone());
    let routes = serve_answer_read(routes, service.clone(), hooks.clone());
    let routes = serve_plan_read_needs(routes, service.clone(), hooks.clone());
    let routes = serve_check_record_visibility(routes, service.clone(), hooks.clone());
    let routes = serve_apply_state_delta(routes, service.clone(), hooks.clone());
    let routes = serve_plan_schema_migration(routes, service.clone(), hooks.clone());
    let routes = serve_hash_bytes(routes, service.clone(), hooks.clone());
    let routes = serve_declare_event_kind(routes, service.clone(), hooks.clone());
    let routes = serve_emit_event(routes, service.clone(), hooks.clone());
    let routes = serve_decide_tenant_operation(routes, service.clone(), hooks.clone());
    let routes = serve_list_my_segments(routes, service.clone(), hooks.clone());
    let routes = serve_count_segment_members(routes, service.clone(), hooks.clone());
    let routes = serve_preview_segment_predicate(routes, service.clone(), hooks.clone());
    let routes = serve_define_trigger(routes, service.clone(), hooks.clone());
    let routes = serve_remove_trigger(routes, service.clone(), hooks.clone());
    let routes = serve_define_automation(routes, service.clone(), hooks.clone());
    let routes = serve_remove_automation(routes, service.clone(), hooks.clone());
    serve_recheck_automation_authority(routes, service, hooks)
}

/// A typed client for the contracts component `kernel` (Kernel) implements.
#[derive(Debug, Clone)]
pub struct KernelClient<K: strata_runtime::Credentials = strata_runtime::NoCredentials> {
    client: strata_runtime::Client<K>,
}

