    /// caller's credentials.
    pub fn new(client: strata_runtime::Client<K>) -> Self {
        Self { client }
    }

    /// The runtime client underneath, for calls with a correlation id or another retry
    /// policy.
    pub fn client(&self) -> &strata_runtime::Client<K> {
        &self.client
    }

