/// What the routes of component `substrate` (Substrate) need from the deployment beyond the implementation of its contracts: the hooks of every one of them.
pub trait SubstrateHooks:
    InstallBundleHooks
    + ParseBundleHooks
    + ParseMarkdownHooks
    + UpgradeBundleHooks
    + RemoveBundleHooks
    + ListInstalledProductsHooks
{
}

impl<
        T: InstallBundleHooks
            + ParseBundleHooks
            + ParseMarkdownHooks
            + UpgradeBundleHooks
            + RemoveBundleHooks
            + ListInstalledProductsHooks,
    > SubstrateHooks for T
{
}

/// Adds the route of every contract component `substrate` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn substrate_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::Substrate + Send + Sync + 'static,
    H: SubstrateHooks,
{
    let routes = serve_install_bundle(routes, service.clone(), hooks.clone());
    let routes = serve_parse_bundle(routes, service.clone(), hooks.clone());
    let routes = serve_parse_markdown(routes, service.clone(), hooks.clone());
    let routes = serve_upgrade_bundle(routes, service.clone(), hooks.clone());
    let routes = serve_remove_bundle(routes, service.clone(), hooks.clone());
    serve_list_installed_products(routes, service, hooks)
}

