/// Adds the route of every contract component `store-contract` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn store_contract_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::StoreContract + Send + Sync + 'static,
    H: StoreContractHooks,
{
    let routes = serve_store_capabilities(routes, service.clone(), hooks.clone());
    let routes = serve_store_health(routes, service.clone(), hooks.clone());
    let routes = serve_list_storage_migrations(routes, service.clone(), hooks.clone());
    let routes = serve_list_store_tenants(routes, service.clone(), hooks.clone());
    let routes = serve_load_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_load_complete_tenant(routes, service.clone(), hooks.clone());
    let routes = serve_commit_transition(routes, service.clone(), hooks.clone());
    let routes = serve_list_events_after(routes, service.clone(), hooks.clone());
    let routes = serve_list_outbox(routes, service.clone(), hooks.clone());
    let routes = serve_mark_outbox_published(routes, service.clone(), hooks.clone());
    let routes = serve_list_journal_after(routes, service.clone(), hooks.clone());
    let routes = serve_put_session(routes, service.clone(), hooks.clone());
    let routes = serve_find_session_by_token(routes, service.clone(), hooks.clone());
    let routes = serve_find_session_by_id(routes, service.clone(), hooks.clone());
    let routes = serve_list_live_sessions(routes, service.clone(), hooks.clone());
    let routes = serve_purge_ended_sessions(routes, service.clone(), hooks.clone());
    let routes = serve_put_account(routes, service.clone(), hooks.clone());
    let routes = serve_find_account(routes, service.clone(), hooks.clone());
    let routes = serve_create_snapshot(routes, service.clone(), hooks.clone());
    let routes = serve_list_snapshots(routes, service.clone(), hooks.clone());
    let routes = serve_load_snapshot(routes, service.clone(), hooks.clone());
    let routes = serve_restore_snapshot(routes, service.clone(), hooks.clone());
    let routes = serve_reset_store(routes, service.clone(), hooks.clone());
    let routes = serve_execute_intent(routes, service.clone(), hooks.clone());
    let routes = serve_execute_read(routes, service.clone(), hooks.clone());
    let routes = serve_load_decision_snapshot(routes, service.clone(), hooks.clone());
    serve_commit_accepted(routes, service, hooks)
}

